INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1265691, 162095, 25397, '<td valign="top">The best ducky idea I have seen yet. :-)</td>', 'The best ducky idea I have seen yet. :-)', '2005-04-02 10:09:48.000000', NULL, 1),
(1265693, 162147, 20115, '<td valign="top">so clever--good job</td>', 'so clever--good job', '2005-04-02 10:10:04.000000', NULL, 1),
(1265700, 162016, 7543, '<td valign="top">Weird stuff, I like it! I think I''m scared....</td>', 'Weird stuff, I like it! I think I''m scared....', '2005-04-02 10:14:55.000000', NULL, 1),
(1265708, 162156, 8624, '<td valign="top">I like the setup here. Next time though, be more careful with your lighting. The hot spots on the blue tarp are distracting.</td>', 'I like the setup here. Next time though, be more careful with your lighting. The hot spots on the blue tarp are distracting.', '2005-04-02 10:26:57.000000', NULL, 1),
(1265711, 161979, 33542, '<td valign="top">lol, it took me a minute... I was like "what''s the string, but where are the little men, OOHHHH, I get it."</td>', 'lol, it took me a minute... I was like "what''s the string, but where are the little men, OOHHHH, I get it."', '2005-04-02 10:28:05.000000', NULL, 1),
(1265712, 162111, 8624, '<td valign="top">I like the blue gauze material as the background and your setup in general but the quality of the picture is pretty bad - way too noisy.</td>', 'I like the blue gauze material as the background and your setup in general but the quality of the picture is pretty bad - way too noisy.', '2005-04-02 10:29:54.000000', NULL, 1),
(1265713, 162035, 33542, '<td valign="top">Entire picture looks slightly out of focus, probably b/c it was dim where you took the pic. Candle flames are overexposed. If you''ve got photoshop you can "darken highlights" to help fix that.</td>', 'Entire picture looks slightly out of focus, probably b/c it was dim where you took the pic. Candle flames are overexposed. If you''ve got photoshop you can "darken highlights" to help fix that.', '2005-04-02 10:30:43.000000', NULL, 1),
(1265715, 162089, 8624, '<td valign="top">extra points for finding a KISS rubber ducky! just when you think Gene Simmons has marketed everything... wow. I lso like how your grapers look like stage lights or audience members. well done!</td>', 'extra points for finding a KISS rubber ducky! just when you think Gene Simmons has marketed everything... wow. I lso like how your grapers look like stage lights or audience members. well done!', '2005-04-02 10:31:17.000000', NULL, 1),
(1265717, 161854, 33542, '<td valign="top">Ahhh, scary duck!  :)</td>', 'Ahhh, scary duck!  :)', '2005-04-02 10:31:31.000000', NULL, 1),
(1265718, 162195, 8624, '<td valign="top">the technical aspects of the picture could be better but this is a very clever idea. I love the little gooly eyes on the grapes. congrats!</td>', 'the technical aspects of the picture could be better but this is a very clever idea. I love the little gooly eyes on the grapes. congrats!', '2005-04-02 10:32:14.000000', NULL, 1),
(1265719, 162147, 8624, '<td valign="top">great use of the grapes. I like the shimmery background too. focus is pretty soft overall, however.</td>', 'great use of the grapes. I like the shimmery background too. focus is pretty soft overall, however.', '2005-04-02 10:33:33.000000', NULL, 1),
(1265720, 162031, 33542, '<td valign="top">I might have upped the saturation a big to make the duck more yellow - unless it made everything else look too weird.</td>', 'I might have upped the saturation a big to make the duck more yellow - unless it made everything else look too weird.', '2005-04-02 10:34:00.000000', NULL, 1),
(1265723, 161976, 8624, '<td valign="top">are the grapes inside the peanuts?</td>', 'are the grapes inside the peanuts?', '2005-04-02 10:35:07.000000', NULL, 1),
(1265731, 161974, 8624, '<td valign="top">this is a nice contrast to the other images in the challenge. great use of the door and wall for your background. I see little dots on the sill that I will assume are the grapes. clever entry!</td>', 'this is a nice contrast to the other images in the challenge. great use of the door and wall for your background. I see little dots on the sill that I will assume are the grapes. clever entry!', '2005-04-02 10:39:15.000000', NULL, 1),
(1265736, 161865, 33542, '<td valign="top">lol. Would have been better if you had been able to get water droplets off the inside I think.</td>', 'lol. Would have been better if you had been able to get water droplets off the inside I think.', '2005-04-02 10:40:27.000000', NULL, 1),
(1265737, 162095, 8624, '<td valign="top">great concept! clever use of the materials. the smashed, thrown grapes was inspired! lighting is pretty harsh and the composition is pretty cluttered overall, but extra points for originality.</td>', 'great concept! clever use of the materials. the smashed, thrown grapes was inspired! lighting is pretty harsh and the composition is pretty cluttered overall, but extra points for originality.', '2005-04-02 10:41:08.000000', NULL, 1),
