(1266798, 161866, 20168, '<td valign="top">Great choice of lighting, composition and focus.  Tells a story with a funny twist. I do like the fading focus on the line of duckygrapes, but would have loved for the first little grape to be in sharp focus.  Pickypicky.  One of my favorites in this challenge.  Excellent photo!</td>', 'Great choice of lighting, composition and focus.  Tells a story with a funny twist. I do like the fading focus on the line of duckygrapes, but would have loved for the first little grape to be in sharp focus.  Pickypicky.  One of my favorites in this challenge.  Excellent photo!', '2005-04-02 23:04:21.000000', NULL, 1),
(1266805, 161986, 20168, '<td valign="top">Cool composition and basic idea.  I love the split level shooting with water below.  The focus seems a bit blurred on the duck, perhaps intentionally smart blurred?  The Light source from the right side is too hot on the bottom three graps and the duck cheek.  Apart from these minor things, one of my favorites to win this strange challenge.</td>', 'Cool composition and basic idea.  I love the split level shooting with water below.  The focus seems a bit blurred on the duck, perhaps intentionally smart blurred?  The Light source from the right side is too hot on the bottom three graps and the duck cheek.  Apart from these minor things, one of my favorites to win this strange challenge.', '2005-04-02 23:06:51.000000', NULL, 1),
(1266807, 162144, 20168, '<td valign="top">Great compositional setup and story relating to the rubber duck''s eyes.  I like the grapes in silhouette and the lighting is excellent.  One of my favorites to ribbon.  Thanks!</td>', 'Great compositional setup and story relating to the rubber duck''s eyes.  I like the grapes in silhouette and the lighting is excellent.  One of my favorites to ribbon.  Thanks!', '2005-04-02 23:08:17.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1266809, 162177, 20168, '<td valign="top">Outstanding compositional choice, and a cool idea, giving this duck some character/style.  I like the richness of the blue background with the water drops, and the grapes revealing the subtle use of light sources (required for the challenge, yet not shown directly). Excellent photo for a strange challenge.</td>', 'Outstanding compositional choice, and a cool idea, giving this duck some character/style.  I like the richness of the blue background with the water drops, and the grapes revealing the subtle use of light sources (required for the challenge, yet not shown directly). Excellent photo for a strange challenge.', '2005-04-02 23:10:25.000000', NULL, 1),
(1266815, 162068, 20168, '<td valign="top">Great lighting choices and composition which causes the eye to move around the frame seeming to understand the image.  My only crit is about hiding the duck behind the glass, even cutting of the duck''s eye with the glass.  Overall, an excellent use of lighting and elements for a cool looking photo.</td>', 'Great lighting choices and composition which causes the eye to move around the frame seeming to understand the image.  My only crit is about hiding the duck behind the glass, even cutting of the duck''s eye with the glass.  Overall, an excellent use of lighting and elements for a cool looking photo.', '2005-04-02 23:16:11.000000', NULL, 1),
(1266817, 161960, 20168, '<td valign="top">Cool concept and execution of this shot.  I love the look of the upside down duck under water.  Nice focus, and great water light play.</td>', 'Cool concept and execution of this shot.  I love the look of the upside down duck under water.  Nice focus, and great water light play.', '2005-04-02 23:17:32.000000', NULL, 1),
