(1271844, 162060, 34741, '<td valign="top">excellent... no comments. i never did better... lol</td>', 'excellent... no comments. i never did better... lol', '2005-04-05 05:17:07.000000', NULL, 1),
(1271846, 162166, 34741, '<td valign="top">I love this pic.</td>', 'I love this pic.', '2005-04-05 05:22:07.000000', NULL, 1),
