(1274111, 162095, 25946, '<td valign="top">Ok. This one made me really laugh.  Great shot.  Hope you do well.</td>', 'Ok. This one made me really laugh.  Great shot.  Hope you do well.', '2005-04-06 06:55:38.000000', NULL, 1),
(1274114, 162025, 25946, '<td valign="top">Cute.  Love the reflection of the duckie in the water. Simple with all the elements and really cute..</td>', 'Cute.  Love the reflection of the duckie in the water. Simple with all the elements and really cute..', '2005-04-06 06:57:52.000000', NULL, 1),
(1274265, 162105, 25355, '<td valign="top">I never realised rubber duckies could be so pushy.<br/> Excellent photo.</td>', 'I never realised rubber duckies could be so pushy. Excellent photo.', '2005-04-06 09:08:13.000000', NULL, 1),
(1274437, 162051, 27562, '<td valign="top">I like your subtle use of the "water" element.  I hope others take the time to look closely at the image and will not score lower thinking you didnt use it.  The DPC might have jumped the shark with this challenge, egh? ;-0</td>', 'I like your subtle use of the "water" element.  I hope others take the time to look closely at the image and will not score lower thinking you didnt use it.  The DPC might have jumped the shark with this challenge, egh? ;-0', '2005-04-06 10:45:53.000000', NULL, 1),
