(1274493, 162076, 27562, '<td valign="top">Excellent idea of using flowers to hide the horizon line.  Good work.</td>', 'Excellent idea of using flowers to hide the horizon line.  Good work.', '2005-04-06 10:56:07.000000', NULL, 1),
(1274510, 162178, 27562, '<td valign="top">Dark and brilliant idea, but I wish the technical aspects of the photo and matched the great concept.</td>', 'Dark and brilliant idea, but I wish the technical aspects of the photo and matched the great concept.', '2005-04-06 11:00:03.000000', NULL, 1),
(1274515, 162156, 27562, '<td valign="top">Great setup but I question the background choice.  The tarps texture and sheen is distracting.  Otherwise an excellent image. Good Work.</td>', 'Great setup but I question the background choice.  The tarps texture and sheen is distracting.  Otherwise an excellent image. Good Work.', '2005-04-06 11:02:02.000000', NULL, 1),
(1274540, 162080, 18349, '<td valign="top">This is my favorite in the challenge.  Excellent idea, pulled off in a skillful manner.  Fabulous!!! ;o)</td>', 'This is my favorite in the challenge.  Excellent idea, pulled off in a skillful manner.  Fabulous!!! ;o)', '2005-04-06 11:08:26.000000', NULL, 1),
(1274590, 161993, 27562, '<td valign="top">Were in the hell did you get that duck?  Makes me want to get the squirt-guns out;-).  Some of the nicest lighting in the challeneg on the ducky. Good work.</td>', 'Were in the hell did you get that duck?  Makes me want to get the squirt-guns out;-).  Some of the nicest lighting in the challeneg on the ducky. Good work.', '2005-04-06 11:25:19.000000', NULL, 1);
