(1280258, 162024, 22734, '<td valign="top">A truly creative effort which deserves its own award. Congratulations on your top 5 finish. I love it.</td>', 'A truly creative effort which deserves its own award. Congratulations on your top 5 finish. I love it.', '2005-04-09 01:12:22.000000', NULL, 0),
(1280259, 161997, 22734, '<td valign="top">What a winner! Great sense of humor and great presentation. Congratulations on your top 5 finish.</td>', 'What a winner! Great sense of humor and great presentation. Congratulations on your top 5 finish.', '2005-04-09 01:13:26.000000', NULL, 0),
(1280261, 162068, 22734, '<td valign="top">A consummate stroke of creativity. Executed with great precision and love. Congratulations on your 6th finish.</td>', 'A consummate stroke of creativity. Executed with great precision and love. Congratulations on your 6th finish.', '2005-04-09 01:16:42.000000', NULL, 0),
